type repositoryFencer struct {
	guards int
	deny   bool
}

func (fencer *repositoryFencer) Current() authority.Snapshot { return authority.Snapshot{} }
func (fencer *repositoryFencer) Guard(_ context.Context, epoch uint64) error {
	fencer.guards++
