func (service PreparationService) PrepareInitial(ctx context.Context, epoch uint64,
	partition string, spec InitialSpec, now time.Time,
) (PreparationReceipt, error) {
	if ctx == nil || service.Repository == nil || service.Receipts == nil || service.Fencer == nil ||
		len(service.ControllerKey) != ed25519.PrivateKeySize || !entityid.Valid(partition) ||
		service.Cell != service.Repository.config.Cell || epoch == 0 || spec.PartitionID != partition {
		return PreparationReceipt{}, errors.New("managed material preparation service is incomplete")
	}
	if err := validateInitialSpec(spec, service.RecipientSigner, now); err != nil {
		return PreparationReceipt{}, err
	}
	if err := service.validateLiveS3Region(spec); err != nil {
		return PreparationReceipt{}, err
	}
	if err := service.validateSubnet(spec); err != nil {
		return PreparationReceipt{}, err
	}
	if err := service.Fencer.Guard(ctx, epoch); err != nil {
		return PreparationReceipt{}, err
	}
	if existing, err := service.current(ctx, partition, spec); err == nil {
		return existing, nil
	} else if !errors.Is(err, authority.ErrNotFound) {
		return PreparationReceipt{}, err
	}
	controllerPublic := service.ControllerKey.Public().(ed25519.PublicKey)
	bundle, object, err := service.Repository.LookupInitial(ctx, partition, spec, controllerPublic)
	if errors.Is(err, ErrMaterialNotFound) {
		bundle, err = GenerateInitial(spec, service.RecipientSigner, now)
		if err != nil {
			return PreparationReceipt{}, err
		}
		if err := service.validateNativeInitial(ctx, spec, bundle); err != nil {
			return PreparationReceipt{}, err
		}
		object, err = service.Repository.CreateInitial(ctx, epoch, partition, spec, bundle, service.ControllerKey)
	} else if err == nil {
		if err := service.validateNativeInitial(ctx, spec, bundle); err != nil {
			return PreparationReceipt{}, err
		}
	}
	if err != nil {
		return PreparationReceipt{}, err
	}
	if err := validateInitialSpec(spec, service.RecipientSigner, time.Now().UTC()); err != nil {
		return PreparationReceipt{}, err
	}
	receipt, err := SignPreparationReceipt(service.Cell, partition, spec, bundle, object, service.ControllerKey, now)
	if err != nil {
		return PreparationReceipt{}, err
	}
	payload, err := protocol.EncodeJSON(receipt)
	if err != nil {
		return PreparationReceipt{}, err
	}
	if err := service.Fencer.Guard(ctx, epoch); err != nil {
		return PreparationReceipt{}, err
	}
	operationID := entityid.Derive("material-preparation", object.SpecSHA256)
	_, commitErr := service.Receipts.CommitMaterialReceipt(ctx, epoch, spec.PlacementDatabaseID,
		partition, operationID, 0, payload)
	if commitErr != nil && !errors.Is(commitErr, authority.ErrConflict) &&
		!errors.Is(commitErr, authority.ErrOutcomeUnknown) {
		return PreparationReceipt{}, commitErr
	}
	confirmed, err := service.current(ctx, partition, spec)
	if err != nil {
		return PreparationReceipt{}, fmt.Errorf("%w: receipt commit: %v; read: %v", ErrMaterialUnknown, commitErr, err)
	}
	if commitErr == nil && confirmed.Signature != receipt.Signature {
		return PreparationReceipt{}, ErrMaterialConflict
	}
	return confirmed, nil
}

// Current returns the R3-committed receipt only after re-reading its exact OCI
// version and authenticating the controller signature and material pins.
func (service PreparationService) Current(ctx context.Context, database, partition string) (PreparationReceipt, error) {
	receipt, _, err := service.CurrentBundle(ctx, database, partition)
	return receipt, err
}

// CurrentBundle returns the authenticated exact OCI bytes with the receipt so
// confidential delivery can use one pinned object read per host request.
func (service PreparationService) CurrentBundle(ctx context.Context, database, partition string) (PreparationReceipt, InitialBundle, error) {
	if len(service.ControllerKey) != ed25519.PrivateKeySize {
		return PreparationReceipt{}, InitialBundle{}, errors.New("managed material receipt reader is incomplete")
	}
	return service.currentBundle(ctx, database, partition, service.ControllerKey.Public().(ed25519.PublicKey))
}

func (service PreparationService) currentBundle(ctx context.Context, database, partition string, controllerKey ed25519.PublicKey) (PreparationReceipt, InitialBundle, error) {
	if ctx == nil || service.Repository == nil || service.Receipts == nil ||
		len(controllerKey) != ed25519.PublicKeySize ||
		!entityid.Valid(database) || !entityid.Valid(partition) ||
		service.Cell != service.Repository.config.Cell {
		return PreparationReceipt{}, InitialBundle{}, errors.New("managed material receipt reader is incomplete")
	}
	entry, err := service.Receipts.ReadMaterialReceipt(ctx, database, partition)
	if err != nil {
		return PreparationReceipt{}, InitialBundle{}, err
	}
	var receipt PreparationReceipt
	if err := json.Unmarshal(entry.Payload, &receipt, json.RejectUnknownMembers(true)); err != nil ||
		receipt.Spec.PlacementDatabaseID != database || receipt.Spec.PartitionID != partition {
		return PreparationReceipt{}, InitialBundle{}, ErrMaterialConflict
	}
	return service.verifyCurrent(ctx, entry, partition, receipt.Spec, controllerKey)
}

func (service PreparationService) validateSubnet(spec InitialSpec) error {
	subnet, err := netip.ParsePrefix(service.AllowedSubnetCIDR)
	if err != nil || !subnet.Addr().Is4() || !subnet.Addr().IsPrivate() || subnet.Masked() != subnet {
		return errors.New("managed material allowed subnet is invalid")
	}
	for _, member := range spec.Members {
		ip, err := netip.ParseAddr(member.ReplicationIP)
		if err != nil || !subnet.Contains(ip) || member.ClientIP != member.ReplicationIP {
			return errors.New("managed member private IP is outside the accepted subnet")
		}
	}
	return nil
}

func (service PreparationService) validateLiveS3Region(spec InitialSpec) error {
	region, err := service.Repository.config.Region.OCIRegion()
	if err != nil || spec.LiveS3.Region != region {
		return errors.New("live S3 region differs from managed material cell")
	}
	return nil
}

func (service PreparationService) current(ctx context.Context, partition string, spec InitialSpec) (PreparationReceipt, error) {
	entry, err := service.Receipts.ReadMaterialReceipt(ctx, spec.PlacementDatabaseID, partition)
	if err != nil {
		return PreparationReceipt{}, err
	}
	receipt, _, err := service.verifyCurrent(ctx, entry, partition, spec, service.ControllerKey.Public().(ed25519.PublicKey))
	return receipt, err
}

func (service PreparationService) verifyCurrent(ctx context.Context, entry authority.LogEntry,
	partition string, spec InitialSpec, controllerKey ed25519.PublicKey,
) (PreparationReceipt, InitialBundle, error) {
	if err := service.validateLiveS3Region(spec); err != nil {
		return PreparationReceipt{}, InitialBundle{}, err
	}
	if err := service.validateSubnet(spec); err != nil {
		return PreparationReceipt{}, InitialBundle{}, err
	}
	if entry.Kind != authority.MutationMaterialReceipt || entry.Sequence == 0 || entry.SubjectKey != spec.PlacementDatabaseID+"."+partition {
		return PreparationReceipt{}, InitialBundle{}, ErrMaterialConflict
	}
	var receipt PreparationReceipt
	if err := json.Unmarshal(entry.Payload, &receipt, json.RejectUnknownMembers(true)); err != nil {
		return PreparationReceipt{}, InitialBundle{}, ErrMaterialConflict
	}
	wire, err := protocol.EncodeJSON(receipt)
	if err != nil || !bytes.Equal(wire, entry.Payload) {
		return PreparationReceipt{}, InitialBundle{}, ErrMaterialConflict
	}
	specSHA, err := specDigest(spec)
	if err != nil || receipt.SpecSHA256 != specSHA {
		return PreparationReceipt{}, InitialBundle{}, ErrMaterialConflict
	}
	bundle, err := service.Repository.ReadPinned(ctx, receipt.Object, controllerKey)
	if err != nil {
		return PreparationReceipt{}, InitialBundle{}, err
	}
	if err := VerifyPreparationReceipt(receipt, controllerKey,
		service.Cell, partition, bundle); err != nil {
		return PreparationReceipt{}, InitialBundle{}, err
	}
	return receipt, bundle, nil
}

repository_write.text:
func (repository *Repository) CreateInitial(ctx context.Context, epoch uint64, partition string,
	spec InitialSpec, bundle InitialBundle, controllerKey ed25519.PrivateKey,
) (ObjectReference, error) {
	if repository == nil || ctx == nil || epoch == 0 || spec.PartitionID != partition ||
		len(controllerKey) != ed25519.PrivateKeySize {
		return ObjectReference{}, errors.New("managed material repository call is invalid")
	}
	if err := repository.fencer.Guard(ctx, epoch); err != nil {
		return ObjectReference{}, err
	}
	specSHA, err := specDigest(spec)
	if err != nil {
		return ObjectReference{}, err
	}
	name, err := repository.objectName(spec.PlacementDatabaseID, partition, 1, specSHA)
	if err != nil {
		return ObjectReference{}, err
	}
	if err := validateBundleForSpec(spec, bundle); err != nil {
		return ObjectReference{}, err
	}
	stored := storedBundle{Version: 2, Region: string(repository.config.Region), Cell: repository.config.Cell,
		Namespace: repository.config.Namespace, Bucket: repository.config.Bucket, KMSKeyID: repository.config.KMSKeyID,
		ObjectName: name, Generation: 1, SpecSHA256: specSHA, Spec: spec, Bundle: bundle}
	input, err := stored.provisioningInput()
	if err != nil {
		return ObjectReference{}, err
	}
	stored.ProvisioningSignature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(controllerKey, input))
	body, err := protocol.EncodeJSON(stored)
	if err != nil || len(body) == 0 || len(body) > maxStoredBundleBytes {
		return ObjectReference{}, errors.New("managed material bundle exceeds its object bound")
	}
	sum := sha256.Sum256(body)
	sha := hex.EncodeToString(sum[:])
	length := int64(len(body))
	checksum := base64.StdEncoding.EncodeToString(sum[:])
	response, putErr := repository.client.PutObject(ctx, objectstorage.PutObjectRequest{
		NamespaceName: new(repository.config.Namespace), BucketName: new(repository.config.Bucket),
		ObjectName: new(name), PutObjectBody: io.NopCloser(bytes.NewReader(body)),
		ContentLength: new(length), ContentType: new("application/json"),
		IfNoneMatch: new("*"), OpcSseKmsKeyId: new(repository.config.KMSKeyID),
		OpcChecksumAlgorithm: objectstorage.PutObjectOpcChecksumAlgorithmSha256,
		OpcContentSha256:     new(checksum),
	})
	// A failed Put may have committed. The read must still match the exact
	// request bytes; a different object is a conflict, not an adopted signer.
	observed, readErr := repository.read(ctx, name, "", "", sha, controllerKey.Public().(ed25519.PublicKey))
	if readErr != nil {
		if errors.Is(readErr, ErrMaterialConflict) {
			return ObjectReference{}, ErrMaterialConflict
		}
		return ObjectReference{}, fmt.Errorf("%w: put: %v; read: %v", ErrMaterialUnknown, putErr, readErr)
	}
	if !bytes.Equal(observed.bytes, body) {
		return ObjectReference{}, ErrMaterialConflict
	}
	if putErr == nil && (response.ETag == nil || *response.ETag != observed.ref.ETag ||
		response.VersionId == nil || *response.VersionId != observed.ref.VersionID) {
		return ObjectReference{}, ErrMaterialConflict
	}
	if err := repository.fencer.Guard(ctx, epoch); err != nil {
		return ObjectReference{}, err
	}
	observed.ref.SpecSHA256 = specSHA
	return observed.ref, nil
}

repository_read.text:
func (repository *Repository) ReadPinned(ctx context.Context, ref ObjectReference,
	controllerKey ed25519.PublicKey,
) (InitialBundle, error) {
	if repository == nil || ctx == nil || ref.VersionID == "" || ref.ETag == "" ||
		!lowerHexDigest(ref.SHA256) || !lowerHexDigest(ref.SpecSHA256) ||
		!repository.validObjectName(ref.Name, ref.SpecSHA256) {
		return InitialBundle{}, errors.New("managed material reference is invalid")
	}
	observed, err := repository.read(ctx, ref.Name, ref.VersionID, ref.ETag, ref.SHA256, controllerKey)
	if err != nil {
		return InitialBundle{}, err
	}
	if observed.ref.VersionID != ref.VersionID || observed.ref.ETag != ref.ETag ||
		observed.ref.SHA256 != ref.SHA256 || observed.ref.SpecSHA256 != ref.SpecSHA256 {
		return InitialBundle{}, ErrMaterialConflict
	}
	return observed.bundle, nil
}

// LookupInitial recovers an object written before its R3 receipt. It returns
// bytes only; the caller must commit a new signed receipt before admission.
func (repository *Repository) LookupInitial(ctx context.Context, partition string, spec InitialSpec,
	controllerKey ed25519.PublicKey,
) (InitialBundle, ObjectReference, error) {
	if repository == nil || ctx == nil || spec.PartitionID != partition ||
		len(controllerKey) != ed25519.PublicKeySize {
		return InitialBundle{}, ObjectReference{}, errors.New("managed material lookup is invalid")
	}
	specSHA, err := specDigest(spec)
	if err != nil {
		return InitialBundle{}, ObjectReference{}, err
	}
	name, err := repository.objectName(spec.PlacementDatabaseID, partition, 1, specSHA)
	if err != nil {
		return InitialBundle{}, ObjectReference{}, err
	}
	observed, err := repository.read(ctx, name, "", "", "", controllerKey)
	if err != nil {
		return InitialBundle{}, ObjectReference{}, err
	}
	if observed.ref.SpecSHA256 != specSHA {
		return InitialBundle{}, ObjectReference{}, ErrMaterialConflict
	}
	return observed.bundle, observed.ref, nil
}

repository_decode.text:
func (repository *Repository) read(ctx context.Context, name, versionID, etag, wantSHA string,
	controllerKey ed25519.PublicKey,
) (observedBundle, error) {
	request := objectstorage.GetObjectRequest{NamespaceName: new(repository.config.Namespace),
		BucketName: new(repository.config.Bucket), ObjectName: new(name)}
	if versionID != "" {
		request.VersionId = new(versionID)
	}
	if etag != "" {
		request.IfMatch = new(etag)
	}
	response, err := repository.client.GetObject(ctx, request)
	if err != nil {
		if service, ok := errors.AsType[objectServiceError](err); ok &&
			service.GetHTTPStatusCode() == http.StatusNotFound {
			return observedBundle{}, ErrMaterialNotFound
		}
		return observedBundle{}, err
	}
	if response.Content == nil {
		return observedBundle{}, ErrMaterialConflict
	}
	defer response.Content.Close()
	if response.ContentLength == nil || *response.ContentLength < 1 || *response.ContentLength > maxStoredBundleBytes ||
		response.ETag == nil || *response.ETag == "" || response.VersionId == nil || *response.VersionId == "" {
		return observedBundle{}, ErrMaterialConflict
	}
	body, err := io.ReadAll(io.LimitReader(response.Content, maxStoredBundleBytes+1))
	if err != nil {
		return observedBundle{}, err
	}
	if len(body) != int(*response.ContentLength) || len(body) > maxStoredBundleBytes {
		return observedBundle{}, ErrMaterialConflict
	}
	sum := sha256.Sum256(body)
	sha := hex.EncodeToString(sum[:])
	if wantSHA != "" && sha != wantSHA || versionID != "" && *response.VersionId != versionID ||
		etag != "" && *response.ETag != etag {
		return observedBundle{}, ErrMaterialConflict
	}
	var stored storedBundle
	if err := json.Unmarshal(body, &stored, json.RejectUnknownMembers(true)); err != nil ||
		stored.Region != string(repository.config.Region) || stored.Cell != repository.config.Cell ||
		stored.Namespace != repository.config.Namespace || stored.Bucket != repository.config.Bucket ||
		stored.KMSKeyID != repository.config.KMSKeyID ||
		stored.ObjectName != name || stored.Generation != 1 ||
		!stored.verifyProvisioning(controllerKey) ||
		!lowerHexDigest(stored.SpecSHA256) || validateBundleForSpec(stored.Spec, stored.Bundle) != nil {
		return observedBundle{}, ErrMaterialConflict
	}
	canonical, err := protocol.EncodeJSON(stored)
	if err != nil || !bytes.Equal(body, canonical) {
		return observedBundle{}, ErrMaterialConflict
	}
	specSHA, err := specDigest(stored.Spec)
	if err != nil || specSHA != stored.SpecSHA256 ||
		!repository.validObjectName(name, specSHA) {
		return observedBundle{}, ErrMaterialConflict
	}
	return observedBundle{ref: ObjectReference{Name: name, VersionID: *response.VersionId,
		ETag: *response.ETag, SHA256: sha, SpecSHA256: stored.SpecSHA256},
		bytes: body, bundle: stored.Bundle}, nil
}

bundle_validation.text:
func validateBundleForSpec(spec InitialSpec, bundle InitialBundle) error {
	if err := validateStoredBundle(bundle); err != nil {
		return err
	}
	if validateSQLTables(spec.SQLTables, spec.Catalogs) != nil ||
		verifyStoredBackupMaterial(spec, bundle) != nil {
		return ErrMaterialConflict
	}
	catalogs, err := initialCatalogs(spec.Catalogs)
	if err != nil {
		return ErrMaterialConflict
	}
	var authorityMembers [2]AuthorityMember
	for index, seat := range spec.Members {
		member := bundle.Members[index]
		_, hasSQL := member.Files[sqlSchemaBundleFileName]
		if member.MemberID != seat.MemberID || hasSQL != (len(spec.SQLTables) > 0) {
			return ErrMaterialConflict
		}
		server := member.Files["server.crt"].Contents
		block, _ := pem.Decode(server)
		if block == nil || block.Type != "CERTIFICATE" {
			return ErrMaterialConflict
		}
		if _, err := tls.X509KeyPair(server, member.Files["server.key"].Contents); err != nil {
			return ErrMaterialConflict
		}
		if !bytes.Equal(member.Files["server-ca.pem"].Contents, member.Files["client-ca.pem"].Contents) ||
			!verifyStoredLiveS3(spec, member) ||
			!bytes.Contains(server, member.Files["server-ca.pem"].Contents) ||
			verifyStoredTLS(seat, member, bundle.Retained) != nil ||
			verifyStoredClientConfig(spec, seat, member) != nil ||
			verifyStoredRegistry(spec, member, bundle.Customer) != nil {
			return ErrMaterialConflict
		}
		_, caPEM := pem.Decode(member.Files["client-chain.pem"].Contents)
		caDigest := sha256.Sum256(caPEM)
		if bundle.Customer.HTTPSCASHA256 != hex.EncodeToString(caDigest[:]) {
			return ErrMaterialConflict
		}
		authorityMembers[index] = AuthorityMember{MemberID: seat.MemberID, Incarnation: seat.Incarnation,
			ServerName: seat.ServerName, FailureDomain: seat.FailureDomain, LeafDER: block.Bytes}
		if !bytes.Equal(member.Files["authority.tbca"].Contents, bundle.Authority.Certificate) ||
			!bytes.Equal(member.Files["trusted-public-key"].Contents, bundle.Authority.TrustedKey) ||
			member.TLSLeafSHA256 != bundle.Authority.MemberLeafPins[index] {
			return ErrMaterialConflict
		}
	}
	recreated, err := SignInitialAuthorityV2(spec.Scope, authorityMembers, catalogs, bundle.Retained.AuthoritySigner)
	if err != nil || !bytes.Equal(recreated.Certificate, bundle.Authority.Certificate) ||
		recreated.ConfigurationID != bundle.Authority.ConfigurationID ||
		!bytes.Equal(recreated.TrustedKey, bundle.Authority.TrustedKey) {
		return ErrMaterialConflict
	}
	if len(spec.SQLTables) > 0 {
		wantSQLBundle, err := encodeSQLSchemaBundle(spec.Scope, recreated.ConfigurationID,
			spec.SQLTables, bundle.Retained.AuthoritySigner)
		if err != nil || !bytes.Equal(wantSQLBundle, bundle.Members[0].Files[sqlSchemaBundleFileName].Contents) ||
			!bytes.Equal(bundle.Members[0].Files[sqlSchemaBundleFileName].Contents,
				bundle.Members[1].Files[sqlSchemaBundleFileName].Contents) {
			return ErrMaterialConflict
		}
	}
	return nil
}

generate_initial.text:
func GenerateInitial(spec InitialSpec, trustedRecipientSigner ed25519.PublicKey, now time.Time) (InitialBundle, error) {
	if err := validateInitialSpec(spec, trustedRecipientSigner, now); err != nil {
		return InitialBundle{}, err
	}
	_, authorityKey, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		return InitialBundle{}, err
	}
	replicationCA, replicationKey, err := generateCA("TerraBase replication", now)
	if err != nil {
		return InitialBundle{}, err
	}
	httpsCA, httpsKey, err := generateCA("TerraBase HTTPS", now)
	if err != nil {
		return InitialBundle{}, err
	}
	var authorityMembers [2]AuthorityMember
	var members [2]MemberBundle
	for index, seat := range spec.Members {
		replicationDER, replicationPEM, replicationPrivate, leafErr := generateLeaf(
			replicationCA, replicationKey, leafKeyEd25519, seat.ServerName, nil, now,
			[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth, x509.ExtKeyUsageClientAuth})
		if leafErr != nil {
			return InitialBundle{}, leafErr
		}
		if len(replicationDER) == 0 || len(replicationDER) > 4096 {
			return InitialBundle{}, ErrMaterialConflict
		}
		_, httpsPEM, httpsPrivate, leafErr := generateLeaf(
			httpsCA, httpsKey, leafKeyP256, seat.ServerName, net.ParseIP(seat.ClientIP), now,
			[]x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth})
		if leafErr != nil {
			return InitialBundle{}, leafErr
		}
		authorityMembers[index] = AuthorityMember{
			MemberID: seat.MemberID, Incarnation: seat.Incarnation,
			ServerName: seat.ServerName, FailureDomain: seat.FailureDomain, LeafDER: replicationDER,
		}
		files := map[string]File{
			"server.crt":             makeFile(append(replicationPEM, replicationCA.RawPEM...)),
			"server.key":             makeFile(replicationPrivate),
			"server-ca.pem":          makeFile(replicationCA.RawPEM),
			"client-ca.pem":          makeFile(replicationCA.RawPEM),
			"client-chain.pem":       makeFile(append(httpsPEM, httpsCA.RawPEM...)),
			"client-private-key.pem": makeFile(httpsPrivate),
		}
		members[index] = MemberBundle{MemberID: seat.MemberID, Files: files}
	}
	catalogs, err := initialCatalogs(spec.Catalogs)
	if err != nil {
		return InitialBundle{}, err
	}
	authority, err := SignInitialAuthorityV2(spec.Scope, authorityMembers, catalogs, authorityKey)
	if err != nil {
		return InitialBundle{}, err
	}
	backupManifest, backupConfig, err := generateBackupMaterial(spec, authority, authorityKey)
	if err != nil {
		return InitialBundle{}, err
	}
	var sqlSchemaBundle []byte
	if len(spec.SQLTables) > 0 {
		sqlSchemaBundle, err = encodeSQLSchemaBundle(spec.Scope, authority.ConfigurationID, spec.SQLTables, authorityKey)
		if err != nil {
			return InitialBundle{}, err
		}
	}
	tokenID, _ := entityid.Parse(entityid.New())
	var tokenSecret [32]byte
	if _, err := rand.Read(tokenSecret[:]); err != nil {
		return InitialBundle{}, err
	}
	defer clear(tokenSecret[:])
	verifier := sha256.New()
	verifier.Write([]byte("TB-APIKEY-V1\x00"))
	verifier.Write(tokenID[:])
	verifier.Write(tokenSecret[:])
	verifierHex := hex.EncodeToString(verifier.Sum(nil))
	token := "tbk1." + tokenID.String() + "." + base64.RawURLEncoding.EncodeToString(tokenSecret[:])
	for index, seat := range spec.Members {
		files := members[index].Files
		files["authority.tbca"] = makeFile(authority.Certificate)
		files["trusted-public-key"] = makeFile(authority.TrustedKey)
		if spec.Backup != nil {
			files[backupManifestName] = backupManifest
			files[backupConfigName] = backupConfig
		}
		if len(sqlSchemaBundle) > 0 {
			files[sqlSchemaBundleFileName] = makeFile(sqlSchemaBundle)
		}
		liveS3, err := spec.LiveS3.ConfigJSON()
		if err != nil {
			return InitialBundle{}, err
		}
		files["signed-v2-s3-config.json"] = makeFile(liveS3)
		registry, err := json.Marshal(apiKeyRegistry{Version: 1, Keys: []apiKeyEntry{{
			ID: tokenID.String(), VerifierSHA256: verifierHex,
			Tenant: spec.Scope.TenantID, Database: spec.Scope.DatabaseID,
			Shard: strconv.FormatUint(spec.Scope.ShardID, 10), Collections: initialCollectionIDs(spec.Catalogs),
			TableIDs:    initialSQLTableIDs(spec.SQLTables),
			Permissions: []string{"read", "write"}, Revoked: false}}})
		if err != nil {
			return InitialBundle{}, err
		}
		files["client-api-keys.json"] = makeFile(registry)
		config, err := json.Marshal(struct {
			Version          uint64 `json:"version"`
			ListenAddress    string `json:"listen_addr"`
			SQLListenAddress string `json:"sql_listen_addr,omitempty"`
			CertificateChain string `json:"certificate_chain"`
			PrivateKey       string `json:"private_key"`
			APIKeyRegistry   string `json:"api_key_registry"`
		}{Version: 1, ListenAddress: net.JoinHostPort(seat.ClientIP, strconv.Itoa(int(seat.ClientPort))),
			SQLListenAddress: sqlListenAddress(seat),
			CertificateChain: filepath.Join(seat.MaterialDirectory, "client-chain.pem"),
			PrivateKey:       filepath.Join(seat.MaterialDirectory, "client-private-key.pem"),
			APIKeyRegistry:   filepath.Join(seat.MaterialDirectory, "client-api-keys.json")})
		if err != nil {
			return InitialBundle{}, err
		}
		files["client-config.json"] = makeFile(config)
		manifest, err := json.Marshal(struct {
			Version                uint64 `json:"version"`
			ClientConfigSHA256     string `json:"client_config_sha256"`
			CertificateChainSHA256 string `json:"certificate_chain_sha256"`
			PrivateKeySHA256       string `json:"private_key_sha256"`
			APIKeyRegistrySHA256   string `json:"api_key_registry_sha256"`
		}{1, files["client-config.json"].SHA256, files["client-chain.pem"].SHA256,
			files["client-private-key.pem"].SHA256, files["client-api-keys.json"].SHA256})
		if err != nil {
			return InitialBundle{}, err
		}
		files["client-managed-manifest.json"] = makeFile(manifest)
		members[index].TLSLeafSHA256 = authority.MemberLeafPins[index]
	}
	customer, err := encryptCustomerToken(spec, token, verifierHex, httpsCA.RawPEM)
	if err != nil {
		return InitialBundle{}, err
	}
	return InitialBundle{Authority: authority, Members: members, Customer: customer,
		Retained: RetainedSecrets{AuthoritySigner: authorityKey, ReplicationCA: replicationKey,
			HTTPSCA: httpsKey}}, nil
}

