func (service CredentialService) Current(ctx context.Context, database, partition string) (
	CredentialState, *CredentialReceipt, error,
) {
	initial, bundle, err := service.Preparation.CurrentBundle(ctx, database, partition)
	if err != nil {
		return CredentialState{}, nil, err
	}
	return service.current(ctx, initial, bundle)
}

func (service CredentialService) current(ctx context.Context, initial PreparationReceipt,
	bundle InitialBundle,
) (CredentialState, *CredentialReceipt, error) {
	if service.Store == nil {
		return CredentialState{}, nil, errors.New("credential store is unavailable")
	}
	initialState, err := InitialCredentialState(initial, bundle)
	if err != nil {
		return CredentialState{}, nil, err
	}
	entry, err := service.Store.ReadClientCredentials(ctx, initial.Spec.PlacementDatabaseID, initial.PartitionID)
	if errors.Is(err, authority.ErrNotFound) {
		return initialState, nil, nil
	}
	if err != nil {
		return CredentialState{}, nil, err
	}
	var receipt CredentialReceipt
	if entry.Kind != authority.MutationClientCredentials || entry.Sequence == 0 ||
		entry.SubjectKey != initial.Spec.PlacementDatabaseID+"."+initial.PartitionID ||
		protocol.DecodeStrict(entry.Payload, &receipt, 1<<20) != nil {
		return CredentialState{}, nil, ErrMaterialConflict
	}
	wire, err := protocol.EncodeJSON(receipt)
	if err != nil || !bytes.Equal(wire, entry.Payload) {
		return CredentialState{}, nil, ErrMaterialConflict
	}
	initialSHA, err := preparationReceiptDigest(initial)
	if err != nil || receipt.DatabaseID != initial.Spec.PlacementDatabaseID ||
		receipt.PartitionID != initial.PartitionID ||
		receipt.Verify(service.Preparation.ControllerKey.Public().(ed25519.PublicKey),
			initialSHA, bundle.Authority.TrustedKey) != nil {
		return CredentialState{}, nil, ErrMaterialConflict
	}
	if err := validateCredentialRegistry(initial.Spec, receipt.State.Registry); err != nil {
		return CredentialState{}, nil, err
	}
	return receipt.State, &receipt, nil
}

// Apply returns a signed pending receipt. Application is successful only after
// both native members report the committed credential generation.
func (service CredentialService) Apply(ctx context.Context, epoch uint64, request CredentialRequest,
	now time.Time,
) (CredentialReceipt, error) {
	if ctx == nil || epoch == 0 || service.Store == nil || service.Preparation.Fencer == nil ||
		len(service.Preparation.ControllerKey) != ed25519.PrivateKeySize ||
		!entityid.Valid(request.DatabaseID) ||
		!entityid.Valid(request.PartitionID) ||
		!entityid.Valid(request.OperationID) ||
		!lowerHexDigest(request.InitialReceiptSHA) || request.ExpectedGeneration == 0 {
		return CredentialReceipt{}, ErrMaterialConflict
	}
	if err := service.Preparation.Fencer.Guard(ctx, epoch); err != nil {
		return CredentialReceipt{}, err
	}
	initial, bundle, err := service.Preparation.CurrentBundle(ctx, request.DatabaseID, request.PartitionID)
	if err != nil {
		return CredentialReceipt{}, err
	}
	initialSHA, err := preparationReceiptDigest(initial)
	if err != nil || initialSHA != request.InitialReceiptSHA {
		return CredentialReceipt{}, ErrMaterialConflict
	}
	requestWire, err := protocol.EncodeJSON(request)
	if err != nil {
		return CredentialReceipt{}, err
	}
	requestSum := sha256.Sum256(requestWire)
	requestSHA := hex.EncodeToString(requestSum[:])
	previous, existing, err := service.current(ctx, initial, bundle)
	if err != nil {
		return CredentialReceipt{}, err
	}
	if existing != nil && existing.State.Generation == request.ExpectedGeneration+1 &&
		existing.RequestSHA256 == requestSHA {
		return *existing, nil
	}
	// An exact committed retry may recover its encrypted token after the
	// recipient grant expires. Freshness still gates every new mutation.
	if err := validateCredentialRequest(request, initial.Spec, service.Preparation.RecipientSigner, now); err != nil {
		return CredentialReceipt{}, err
	}
	if previous.Generation != request.ExpectedGeneration || previous.Generation == ^uint64(0) {
		return CredentialReceipt{}, authority.ErrConflict
	}
	registry, customer, err := applyCredentialChange(previous.Registry, request, initial.Spec, bundle, now)
	if err != nil {
		return CredentialReceipt{}, err
	}
	state, err := SignCredentialState(previous.Generation+1, initialSHA, registry,
		bundle.Retained.AuthoritySigner)
	if err != nil {
		return CredentialReceipt{}, err
	}
	previousSHA, err := CredentialStateDigest(previous)
	if err != nil {
		return CredentialReceipt{}, err
	}
	receipt := CredentialReceipt{Version: 1, DatabaseID: request.DatabaseID,
		PartitionID: request.PartitionID, RequestSHA256: requestSHA,
		PreviousSHA256: previousSHA, State: state, Customer: customer}
	if err := receipt.sign(service.Preparation.ControllerKey); err != nil {
		return CredentialReceipt{}, err
	}
	payload, err := protocol.EncodeJSON(receipt)
	if err != nil || len(payload) > 1<<20 {
		return CredentialReceipt{}, ErrMaterialConflict
	}
	var expectedSequence uint64
	if existing != nil {
		entry, err := service.Store.ReadClientCredentials(ctx, request.DatabaseID, request.PartitionID)
		if err != nil {
			return CredentialReceipt{}, err
		}
		expectedSequence = entry.Sequence
	}
	if err := service.Preparation.Fencer.Guard(ctx, epoch); err != nil {
		return CredentialReceipt{}, err
	}
	_, commitErr := service.Store.CommitClientCredentials(ctx, epoch, request.DatabaseID,
		request.PartitionID, request.OperationID, expectedSequence, payload)
	confirmedState, confirmed, readErr := service.current(ctx, initial, bundle)
	if readErr != nil {
		return CredentialReceipt{}, fmt.Errorf("%w: commit: %v; read: %v", ErrMaterialUnknown, commitErr, readErr)
	}
	if confirmed != nil && confirmedState.Generation == receipt.State.Generation &&
		confirmed.RequestSHA256 == requestSHA && confirmed.Signature == receipt.Signature {
		return *confirmed, nil
	}
	if commitErr != nil {
		return CredentialReceipt{}, commitErr
	}
	return CredentialReceipt{}, ErrMaterialConflict
}

func validateCredentialRequest(request CredentialRequest, spec InitialSpec,
	recipientSigner ed25519.PublicKey, now time.Time,
) error {
	if request.DatabaseID != spec.PlacementDatabaseID || request.PartitionID != spec.PartitionID {
		return ErrMaterialConflict
	}
	switch request.Action {
	case CredentialRotate:
		if request.KeyID != "" {
			return ErrMaterialConflict
		}
		grantSpec := spec
		grantSpec.Recipient = request.Recipient
		return validateInitialSpec(grantSpec, recipientSigner, now)
	case CredentialRevoke:
		if !entityid.Valid(request.KeyID) ||
			len(request.Recipient.PublicKey) != 0 || len(request.Recipient.Signature) != 0 ||
			!request.Recipient.ExpiresAt.IsZero() {
			return ErrMaterialConflict
		}
		return nil
	default:
		return ErrMaterialConflict
	}
}

func applyCredentialChange(current []byte, request CredentialRequest, spec InitialSpec,
	bundle InitialBundle, now time.Time,
) ([]byte, *CustomerEnvelope, error) {
	var registry apiKeyRegistry
	if err := json.Unmarshal(current, &registry, json.RejectUnknownMembers(true)); err != nil ||
		registry.Version != 1 || len(registry.Keys) == 0 || len(registry.Keys) > 128 {
		return nil, nil, ErrMaterialConflict
	}
	switch request.Action {
	case CredentialRevoke:
		found := false
		for index := range registry.Keys {
			if registry.Keys[index].ID == request.KeyID && !registry.Keys[index].Revoked {
				registry.Keys[index].Revoked = true
				found = true
			}
		}
		if !found {
			return nil, nil, ErrMaterialConflict
		}
	case CredentialRotate:
		if len(registry.Keys) == 128 {
			return nil, nil, ErrMaterialConflict
		}
		identifier, _ := entityid.Parse(entityid.New())
		var secret [32]byte
		if _, err := rand.Read(secret[:]); err != nil {
			return nil, nil, err
		}
		defer clear(secret[:])
		id := identifier.String()
		for _, key := range registry.Keys {
			if key.ID == id {
				return nil, nil, ErrMaterialConflict
			}
		}
		verifier := sha256.New()
		verifier.Write([]byte("TB-APIKEY-V1\x00"))
		verifier.Write(identifier[:])
		verifier.Write(secret[:])
		verifierSHA := hex.EncodeToString(verifier.Sum(nil))
		registry.Keys = append(registry.Keys, apiKeyEntry{ID: id, VerifierSHA256: verifierSHA,
			Tenant: spec.Scope.TenantID, Database: spec.Scope.DatabaseID,
			Shard:       strconv.FormatUint(spec.Scope.ShardID, 10),
			Collections: initialCollectionIDs(spec.Catalogs), TableIDs: initialSQLTableIDs(spec.SQLTables),
			Permissions: []string{"read", "write"}})
		grantSpec := spec
		grantSpec.Recipient = request.Recipient
		chain := bundle.Members[0].Files["client-chain.pem"].Contents
		_, caPEM := pem.Decode(chain)
		if len(caPEM) == 0 {
			return nil, nil, ErrMaterialConflict
		}
		// The recipient sees the raw key only inside the encrypted envelope.
		token := "tbk1." + id + "." + base64.RawURLEncoding.EncodeToString(secret[:])
		customer, err := encryptCustomerToken(grantSpec, token, verifierSHA, caPEM)
		if err != nil {
			return nil, nil, err
		}
		wire, err := protocol.EncodeJSON(registry)
		return wire, &customer, err
	default:
		return nil, nil, ErrMaterialConflict
	}
	wire, err := protocol.EncodeJSON(registry)
	if err != nil || len(wire) > maxCredentialRegistryBytes {
		return nil, nil, ErrMaterialConflict
	}
	return wire, nil, nil
}

func validateCredentialRegistry(spec InitialSpec, wire []byte) error {
	var registry apiKeyRegistry
	if err := json.Unmarshal(wire, &registry, json.RejectUnknownMembers(true)); err != nil ||
		registry.Version != 1 || len(registry.Keys) == 0 || len(registry.Keys) > 128 {
		return ErrMaterialConflict
	}
	seen := make(map[string]bool, len(registry.Keys))
	for _, key := range registry.Keys {
		if !entityid.Valid(key.ID) || seen[key.ID] || !lowerHexDigest(key.VerifierSHA256) ||
			key.Tenant != spec.Scope.TenantID || key.Database != spec.Scope.DatabaseID ||
			key.Shard != strconv.FormatUint(spec.Scope.ShardID, 10) ||
			len(key.Permissions) != 2 || key.Permissions[0] != "read" || key.Permissions[1] != "write" ||
			!slicesEqual(key.Collections, initialCollectionIDs(spec.Catalogs)) ||
			!slicesEqual(key.TableIDs, initialSQLTableIDs(spec.SQLTables)) {
			return ErrMaterialConflict
		}
		seen[key.ID] = true
	}
	return nil
}

func slicesEqual(left, right []string) bool {
	if len(left) != len(right) {
		return false
	}
	for index := range left {
		if left[index] != right[index] {
			return false
		}
	}
	return true
}

credential_state.text:
func (state CredentialState) signingMaterial() []byte {
	material := make([]byte, 0, len(credentialAuthorityDomain)+32+65+len(state.Registry))
	material = append(material, credentialAuthorityDomain...)
	material = strconv.AppendUint(material, state.Generation, 10)
	material = append(material, 0)
	material = append(material, state.InitialReceiptSHA256...)
	material = append(material, 0)
	return append(material, state.Registry...)
}

func SignCredentialState(generation uint64, initialReceiptSHA string, registry []byte,
	authorityKey ed25519.PrivateKey,
) (CredentialState, error) {
	if generation == 0 || !lowerHexDigest(initialReceiptSHA) || len(registry) == 0 ||
		len(registry) > maxCredentialRegistryBytes || len(authorityKey) != ed25519.PrivateKeySize {
		return CredentialState{}, ErrMaterialConflict
	}
	sum := sha256.Sum256(registry)
	state := CredentialState{Version: 1, Generation: generation, InitialReceiptSHA256: initialReceiptSHA,
		RegistrySHA256: hex.EncodeToString(sum[:]), Registry: bytes.Clone(registry)}
	state.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(authorityKey, state.signingMaterial()))
	return state, nil
}

func VerifyCredentialState(state CredentialState, initialReceiptSHA string, authorityKey ed25519.PublicKey) error {
	if state.Version != 1 || state.Generation == 0 || state.InitialReceiptSHA256 != initialReceiptSHA ||
		!lowerHexDigest(state.RegistrySHA256) || len(state.Registry) == 0 ||
		len(state.Registry) > maxCredentialRegistryBytes || len(authorityKey) != ed25519.PublicKeySize {
		return ErrMaterialConflict
	}
	sum := sha256.Sum256(state.Registry)
	signature, err := base64.RawURLEncoding.DecodeString(state.Signature)
	if err != nil || len(signature) != ed25519.SignatureSize ||
		hex.EncodeToString(sum[:]) != state.RegistrySHA256 ||
		!ed25519.Verify(authorityKey, state.signingMaterial(), signature) {
		return ErrMaterialConflict
	}
	var registry apiKeyRegistry
	if err := json.Unmarshal(state.Registry, &registry, json.RejectUnknownMembers(true)); err != nil ||
		registry.Version != 1 || len(registry.Keys) == 0 || len(registry.Keys) > 128 {
		return ErrMaterialConflict
	}
	for _, key := range registry.Keys {
		if !validSQLTableGrantIDs(key.TableIDs) {
			return ErrMaterialConflict
		}
	}
	canonical, err := protocol.EncodeJSON(registry)
	if err != nil || !bytes.Equal(canonical, state.Registry) || bytes.Contains(state.Registry, []byte("tbk1.")) {
		return ErrMaterialConflict
	}
	return nil
}

func validSQLTableGrantIDs(ids []string) bool {
	if len(ids) > sqlSchemaBundleMaxRows {
		return false
	}
	var previous []byte
	for _, id := range ids {
		decoded, err := entityid.Parse(id)
		if err != nil || len(decoded) != 16 || !entityid.Valid(id) ||
			previous != nil && bytes.Compare(previous, decoded[:]) >= 0 {
			return false
		}
		previous = decoded[:]
	}
	return true
}

func CredentialStateDigest(state CredentialState) (string, error) {
	wire, err := protocol.EncodeJSON(state)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:]), nil
}

func InitialCredentialState(receipt PreparationReceipt, bundle InitialBundle) (CredentialState, error) {
	initialSHA, err := preparationReceiptDigest(receipt)
	if err != nil {
		return CredentialState{}, err
	}
	left := bundle.Members[0].Files["client-api-keys.json"].Contents
	right := bundle.Members[1].Files["client-api-keys.json"].Contents
	if !bytes.Equal(left, right) || verifyStoredRegistry(receipt.Spec, bundle.Members[0], bundle.Customer) != nil {
		return CredentialState{}, ErrMaterialConflict
	}
	return SignCredentialState(1, initialSHA, left, bundle.Retained.AuthoritySigner)
}

func preparationReceiptDigest(receipt PreparationReceipt) (string, error) {
	wire, err := protocol.EncodeJSON(receipt)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(wire)
	return hex.EncodeToString(sum[:]), nil
}

type CredentialAction string

const (
	CredentialRotate CredentialAction = "rotate"
	CredentialRevoke CredentialAction = "revoke"
)

// CredentialRequest is the payload inside an operator-signed NATS envelope.
// ExpectedGeneration and operation ID make retries and contention explicit.
type CredentialRequest struct {
	DatabaseID         string           `json:"database_id"`
	PartitionID        string           `json:"partition_id"`
	InitialReceiptSHA  string           `json:"initial_receipt_sha256"`
	ExpectedGeneration uint64           `json:"expected_generation"`
	OperationID        string           `json:"operation_id"`
	Action             CredentialAction `json:"action"`
	KeyID              string           `json:"key_id,omitempty"`
	Recipient          RecipientGrant   `json:"recipient,omitzero"`
}

type CredentialReceipt struct {
	Version         uint64            `json:"version"`
	DatabaseID      string            `json:"database_id"`
	PartitionID     string            `json:"partition_id"`
	RequestSHA256   string            `json:"request_sha256"`
	PreviousSHA256  string            `json:"previous_sha256"`
	State           CredentialState   `json:"state"`
	Customer        *CustomerEnvelope `json:"customer,omitempty"`
	ControllerKeyID string            `json:"controller_key_id"`
	Signature       string            `json:"signature"`
}

// CredentialReply keeps a signed initial receipt and its authority key beside
// the new receipt so an offline operator can authenticate the customer token.
type CredentialReply struct {
	Initial      PreparationReceipt `json:"initial"`
	AuthorityKey []byte             `json:"authority_key"`
	Receipt      CredentialReceipt  `json:"receipt"`
}

func VerifyCredentialReply(reply CredentialReply, request CredentialRequest,
	controllerKey ed25519.PublicKey, cell string,
) error {
	if reply.Initial.Spec.PlacementDatabaseID != request.DatabaseID ||
		reply.Initial.PartitionID != request.PartitionID ||
		verifyPreparationSignature(reply.Initial, controllerKey, cell, request.PartitionID) != nil {
		return ErrMaterialConflict
	}
	initialSHA, err := preparationReceiptDigest(reply.Initial)
	if err != nil || initialSHA != request.InitialReceiptSHA ||
		len(reply.AuthorityKey) != ed25519.PublicKeySize {
		return ErrMaterialConflict
	}
	keySHA := sha256.Sum256(reply.AuthorityKey)
	if hex.EncodeToString(keySHA[:]) != reply.Initial.TrustedKeySHA256 ||
		reply.Receipt.DatabaseID != request.DatabaseID ||
		reply.Receipt.PartitionID != request.PartitionID ||
		reply.Receipt.State.Generation != request.ExpectedGeneration+1 ||
		reply.Receipt.Verify(controllerKey, initialSHA, reply.AuthorityKey) != nil {
		return ErrMaterialConflict
	}
	wire, err := protocol.EncodeJSON(request)
	if err != nil {
		return err
	}
	requestSHA := sha256.Sum256(wire)
	if hex.EncodeToString(requestSHA[:]) != reply.Receipt.RequestSHA256 ||
		request.Action == CredentialRotate && reply.Receipt.Customer == nil ||
		request.Action == CredentialRevoke && reply.Receipt.Customer != nil {
		return ErrMaterialConflict
	}
	return nil
}

func (receipt CredentialReceipt) signingMaterial() ([]byte, error) {
	receipt.Signature = ""
	wire, err := protocol.EncodeJSON(receipt)
	if err != nil {
		return nil, err
	}
	return append([]byte(credentialReceiptDomain), wire...), nil
}

func (receipt CredentialReceipt) Verify(controllerKey ed25519.PublicKey,
	initialSHA string, authorityKey ed25519.PublicKey,
) error {
	if receipt.Version != 1 || !entityid.Valid(receipt.DatabaseID) ||
		!entityid.Valid(receipt.PartitionID) || !lowerHexDigest(receipt.RequestSHA256) ||
		!lowerHexDigest(receipt.PreviousSHA256) || receipt.State.Generation < 2 ||
		len(controllerKey) != ed25519.PublicKeySize ||
		VerifyCredentialState(receipt.State, initialSHA, authorityKey) != nil {
		return ErrMaterialConflict
	}
	keyID, err := protocol.KeyID(controllerKey)
	if err != nil || keyID != receipt.ControllerKeyID {
		return ErrMaterialConflict
	}
	signature, err := base64.RawURLEncoding.DecodeString(receipt.Signature)
	material, materialErr := receipt.signingMaterial()
	if err != nil || materialErr != nil || len(signature) != ed25519.SignatureSize ||
		!ed25519.Verify(controllerKey, material, signature) {
		return ErrMaterialConflict
	}
	if receipt.Customer != nil {
		var registry apiKeyRegistry
		if err := json.Unmarshal(receipt.State.Registry, &registry, json.RejectUnknownMembers(true)); err != nil ||
			!validCredentialCustomer(*receipt.Customer, registry) {
			return ErrMaterialConflict
		}
	}
	return nil
}

func validCredentialCustomer(customer CustomerEnvelope, registry apiKeyRegistry) bool {
	if customer.Version != 2 || !lowerHexDigest(customer.VerifierSHA256) ||
		!lowerHexDigest(customer.HTTPSCASHA256) ||
		!entityid.Valid(customer.TokenID) ||
		!canonicalCredentialEncoding(customer.EphemeralPublicKey, 32) ||
		!canonicalCredentialEncoding(customer.Nonce, 12) ||
		!canonicalCredentialCiphertext(customer.Ciphertext) {
		return false
	}
	for _, key := range registry.Keys {
		if key.ID == customer.TokenID && key.VerifierSHA256 == customer.VerifierSHA256 && !key.Revoked {
			return true
		}
	}
	return false
}

func canonicalCredentialEncoding(value string, size int) bool {
	decoded, err := base64.RawURLEncoding.DecodeString(value)
	return err == nil && len(decoded) == size && base64.RawURLEncoding.EncodeToString(decoded) == value
}

func canonicalCredentialCiphertext(value string) bool {
	decoded, err := base64.RawURLEncoding.DecodeString(value)
	return err == nil && len(decoded) >= 16 && len(decoded) <= maxCustomerPlaintextBytes+16 &&
		base64.RawURLEncoding.EncodeToString(decoded) == value
}

func (receipt *CredentialReceipt) sign(controllerKey ed25519.PrivateKey) error {
	if receipt == nil || len(controllerKey) != ed25519.PrivateKeySize {
		return errors.New("credential receipt signer is invalid")
	}
	keyID, err := protocol.KeyID(controllerKey.Public().(ed25519.PublicKey))
	if err != nil {
		return err
	}
	receipt.ControllerKeyID = keyID
	material, err := receipt.signingMaterial()
	if err != nil {
		return err
	}
	receipt.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(controllerKey, material))
	return nil
}

