func (target LiveS3Target) ConfigJSON() ([]byte, error) {
	if err := target.Validate(); err != nil {
		return nil, err
	}
	data, err := json.Marshal(struct {
		Version       uint64         `json:"version"`
		AckProfile    string         `json:"ack_profile"`
		Bucket        string         `json:"bucket"`
		Region        string         `json:"region"`
		Endpoint      string         `json:"endpoint,omitempty"`
		NativeOCIRoot *NativeOCIRoot `json:"native_oci_root,omitempty"`
	}{Version: 1, AckProfile: "object_durable", Bucket: target.Bucket,
		Region: target.Region, Endpoint: target.Endpoint, NativeOCIRoot: target.NativeOCIRoot})
	if err != nil || len(data) > 16<<10 {
		return nil, errors.New("live S3 config exceeds its native bound")
	}
	return data, nil
}

// Digest mirrors TerraBase's target_digest: credentials and config JSON
// formatting cannot change the persistent ObjectDurable root identity.
func (target LiveS3Target) Digest() (string, error) {
	if err := target.Validate(); err != nil {
		return "", err
	}
	hash := sha256.New()
	domain := s3TargetDomain
	parts := []string{target.Region, target.Bucket, target.Endpoint}
	if root := target.NativeOCIRoot; root != nil {
		domain = nativeOCIRootTargetDomain
		parts = []string{target.Region, root.Namespace, target.Bucket, target.Endpoint,
			nativeOCIRootPrefix, nativeOCIProbePrefix}
	}
	hash.Write([]byte(domain))
	for _, part := range parts {
		var length [8]byte
		binary.BigEndian.PutUint64(length[:], uint64(len(part)))
		hash.Write(length[:])
		hash.Write([]byte(part))
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

func verifyStoredLiveS3(spec InitialSpec, member MemberBundle) bool {
	config, err := spec.LiveS3.ConfigJSON()
	if err != nil {
		return false
	}
	return bytes.Equal(member.Files["signed-v2-s3-config.json"].Contents, config)
}

managed_path.text:
func ManagedMountPath(root string, member ManagedMemberBinding) (string, error) {
	paths, err := runtimePaths(root, ManagedMemberLaunch{Member: member})
	if err != nil {
		return "", err
	}
	return paths.mount, nil
}

// ManagedMaterialPath is the exact host-owned directory for one signed member
// attempt. Preparation uses this path so client configuration cannot redirect
// a host to operator-chosen material.
func ManagedMaterialPath(root string, member ManagedMemberBinding) (string, error) {
	paths, err := runtimePaths(root, ManagedMemberLaunch{Member: member})
	if err != nil {
		return "", err
	}
	return paths.material, nil
}

runtime_paths.text:
func runtimePaths(root string, launch ManagedMemberLaunch) (managedRuntimePaths, error) {
	if !filepath.IsAbs(root) || filepath.Clean(root) != root || root == "/" {
		return managedRuntimePaths{}, errors.New("managed runtime root must be a clean absolute directory")
	}
	scope := launch.Member.Scope
	if err := validateManagedMemberBinding(launch.Member); err != nil {
		return managedRuntimePaths{}, err
	}
	sum := sha256.Sum256([]byte(scope.ClusterID + "/" + scope.TenantID + "/" + scope.DatabaseID + "/" +
		strconv.FormatUint(scope.ShardID, 10) + "/" + scope.MemberID + "/" + scope.Incarnation + "/" +
		strconv.FormatUint(launch.Member.HostAttempt, 10)))
	memberDir := filepath.Join(root, hex.EncodeToString(sum[:16]))
	paths := managedRuntimePaths{
		memberDir:  memberDir,
		mount:      filepath.Join(memberDir, "volume"),
		material:   filepath.Join(memberDir, "material"),
		socket:     filepath.Join(memberDir, "control", "member.sock"),
		nativeRoot: filepath.Join(memberDir, "native-root.sock"),
	}
	if len(paths.socket) >= 108 || len(paths.nativeRoot) >= 108 {
		return managedRuntimePaths{}, errors.New("managed socket path exceeds Unix limit")
	}
	return paths, nil
}

entityid.text:
// New returns a cryptographically random ULID, monotonic within a millisecond.
func New() string { return NewAt(time.Now()) }

// NewAt stamps an ID with the record's time. The entropy reader is shared and
// serialized because the library's monotonic reader is not concurrency-safe.
func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

// Parse accepts only nonzero, uppercase, 26-character Crockford ULIDs.
func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

